import os
import shutil

from configparser import ConfigParser
from glob import glob
from pathlib import Path
from string import Template
from typing import List, Dict

from rbbuild.core.paths import Paths
from rbbuild.core.runtime_settings import RuntimeSettings
from rbbuild.core.toolchain import Toolchain
from rbbuild.librbb.term import term

# Files generated by default (without --generate-files)
_DEFAULT_FILES = [
    'rbbuild.toml',
    'Jenkinsfile',
    'tasks.json',
]

# All files that can be generated on explicit request
_ALL_FILES = [
    *_DEFAULT_FILES,
    'CMakeLists.txt',
    'pyproject.toml',
    '.gitignore',
]


class ProjectFileGenerator:

    def __init__(self, paths: Paths, toolchain: Toolchain, settings: RuntimeSettings):
        self.paths     = paths
        self.toolchain = toolchain
        self.settings  = settings

    # ------------------------------------------------------------------
    # Source-type detection
    # ------------------------------------------------------------------

    # Return a dict of detected source language types under path.
    # Scans recursively.
    def _detect_source_types(self, path: Path) -> Dict[str, Path]:
        result = {
            'c_cpp': [],   # C/C++ files
            'python': [],  # Python files
        }

        for pat in ['*.c', '*.cc', '*.cpp', '*.cxx']:
            result['c_cpp'].extend([*path.rglob(pat)])
        if not result['c_cpp']:
            del result['c_cpp']

        for pat in ['*.py']:
            result['python'].extend([*path.rglob(pat)])

        if not result['python']:
            del result['python']

        return result

    # ------------------------------------------------------------------
    # Individual file generators
    # ------------------------------------------------------------------

    def _generate_rbbuild_toml(self, dest_path: Path):
        out_file = dest_path / 'rbbuild.toml'
        if out_file.exists():
            return

        in_file = self.paths.templates / 'rbbuild.toml.in'
        with open(in_file, 'r') as fd:
            content = fd.read()

        term.info(f'Creating {out_file} ...')
        with open(out_file, 'w') as fd:
            fd.write(content)


    def _generate_jenkinsfile(self, dest_path: Path):
        out_file = dest_path / 'Jenkinsfile'
        if out_file.exists():
            return

        in_file = self.paths.templates / 'Jenkinsfile.in'
        with open(in_file, 'r') as fd:
            content = fd.read()

        content = Template(content).substitute(
            _RBB_PLATFORM     = self.toolchain.platform,
            _RBB_TOOLCHAIN_ID = self.toolchain.name,
            _RBB_PROFILE      = self.settings.profile_name,
        )

        term.info(f'Creating {out_file} ...')
        with open(out_file, 'w') as fd:
            fd.write(content)


    def _generate_cmakelists(self, dest_path: Path, pkgname: str):
        out_file = dest_path / 'CMakeLists.txt'
        if out_file.exists():
            return

        cur_path = Path.cwd()
        os.chdir(dest_path)
        try:
            sources = []
            include = 'include' if (dest_path / 'include').exists() else ''

            for sdir in ['', 'src', 'source', 'sources']:
                for cpattern in ['*.c', '*.cc', '*.cpp']:
                    p = os.path.sep.join([sdir, cpattern]) if sdir else cpattern
                    sources += glob(p)

            if not sources:
                in_file = self.paths.templates / 'CMakeLists.txt.in'
            else:
                in_file = self.paths.templates / 'CMakeLists.txt_with_sources.in'
                # On Windows, paths are separated by \\, which causes problems in CMake.
                sources = [s.replace('\\', '/') for s in sources]

            with open(in_file, 'r') as fd:
                content = fd.read()

            content = Template(content).safe_substitute(
                _RBB_PROJECT_NAME = pkgname,
                _RBB_SOURCES      = ' '.join(sources),
                _RBB_INCLUDE_DIR  = include,
            )

            term.info(f'Creating {out_file} ...')
            with open('CMakeLists.txt', 'w') as fd:
                fd.write(content)
        finally:
            os.chdir(cur_path)


    def _generate_package_dir(self, dest_path: Path, module_name: str):
        for pyfile in dest_path.glob('*.py'):
            raise RuntimeError(f'{pyfile.name}: Top-level Python files must be moved into ({module_name}/)')

        pkg_dir = dest_path / module_name
        pkg_dir.mkdir(parents=True, exist_ok=True)

        init_file = pkg_dir / '__init__.py'
        if not init_file.exists():
            term.info(f'Creating {init_file} ...')
            init_file.touch()


    def _generate_pyproject_toml(self, dest_path: Path, pkgname: str, files: List[Path]):
        out_file = dest_path / 'pyproject.toml'
        if out_file.exists():
            return

        self._generate_package_dir(dest_path, pkgname)

        in_file = self.paths.templates / 'pyproject.toml.in'
        with open(in_file, 'r') as fd:
            content = fd.read()

        parser = ConfigParser(strict=False)
        parser.read(Path('~/.gitconfig').expanduser())

        pkg_files = set()
        for f in files:
            pkg_files.add(f.parts[0])

        content = Template(content).safe_substitute(
            _RBB_PROJECT_NAME   = pkgname,
            _RBB_USER_NAME      = parser.get('user', 'name', fallback=''),
            _RBB_USER_EMAIL     = parser.get('user', 'email', fallback=''),
            _RBB_PYTHON_SOURCES = list(pkg_files),
        )

        term.info(f'Creating {out_file} ...')
        with open(out_file, 'w') as fd:
            fd.write(content)


    def _generate_gitignore(self, dest_path: Path):
        in_file  = self.paths.templates / '.gitignore'
        out_file = dest_path / '.gitignore'
        if out_file.exists():
            return
        term.info(f'Creating {out_file} ...')
        shutil.copyfile(in_file, out_file)


    def _generate_tasks_json(self, dest_path: Path):
        vscode_path = dest_path / '.vscode'
        out_file    = vscode_path / 'tasks.json'
        in_file     = self.paths.templates / 'vscode' / 'tasks.json'
        if out_file.exists():
            return
        if not vscode_path.exists():
            term.info(f'Creating {vscode_path} ...')
            vscode_path.mkdir(exist_ok=True)
        term.info(f'Symlink {in_file} to .vscode ...')
        try:
            out_file.symlink_to(in_file)
        except OSError:
            term.warning(str(in_file), 'Symlinks are not available - making copy instead')
            shutil.copy(in_file, out_file)

    # ------------------------------------------------------------------
    # Public entry point
    # ------------------------------------------------------------------

    # Generate project scaffold files in dest_path.
    # files: explicit list of file names to generate. When None (default), the set
    # is determined automatically: rbbuild.toml and Jenkinsfile are always generated;
    # CMakeLists.txt is added when C/C++ source files are found;
    # pyproject.toml is added when Python source files are found.
    def create_files(self, dest_path: Path, pkgname: str, files: list = None):
        if not dest_path.exists():
            term.info(f'Creating {dest_path} ...')
            dest_path.mkdir(parents=True, exist_ok=True, mode=0o755)

        source_types = self._detect_source_types(dest_path)

        if files is None:
            files = list(_DEFAULT_FILES)
            if 'c_cpp' in source_types:
                files.append('CMakeLists.txt')
            if 'python' in source_types:
                files.append('pyproject.toml')
                if 'rbbuild.toml' in files:
                    files.remove('rbbuild.toml')

        for fname in files:
            if fname == 'rbbuild.toml':
                self._generate_rbbuild_toml(dest_path)
            elif fname == 'Jenkinsfile':
                self._generate_jenkinsfile(dest_path)
            elif fname == 'CMakeLists.txt':
                self._generate_cmakelists(dest_path, pkgname)
            elif fname == 'pyproject.toml':
                self._generate_pyproject_toml(dest_path, pkgname, source_types['python'])
            elif fname == '.gitignore':
                self._generate_gitignore(dest_path)
            elif fname == 'tasks.json':
                self._generate_tasks_json(dest_path)
            else:
                term.warning(fname, 'Unknown file name — skipping')
